<#
.SYNOPSIS
    Verifies a built RockWeb tree contains every essential assembly, compiled
    Obsidian block, and non-stub styles-v2 stylesheet before packaging.

.DESCRIPTION
    Extracted from pr-test-artifact.yml's "Verify Build Artifacts" step so both
    CI (ubuntu-latest / windows-latest) and local MacBook builds run the exact
    same completeness gates, and so Pester can test every gate directly.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $false)][string]$RockWebPath = 'RockWeb',
    [Parameter(Mandatory = $false)][string]$ResolvedRefreshCount = '',
    [Parameter(Mandatory = $false)][string]$UnresolvedRefreshCount = ''
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Test-RockWebBuild {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)][string]$RootPath
    )

    $failures = New-Object System.Collections.Generic.List[string]
    $warnings = New-Object System.Collections.Generic.List[string]

    # Prefer git's RockWeb/Bin casing on case-sensitive filesystems; fall back to bin.
    $binDir = Join-Path $RootPath 'Bin'
    if (-not (Test-Path -LiteralPath $binDir)) {
        $altBin = Join-Path $RootPath 'bin'
        if (Test-Path -LiteralPath $altBin) { $binDir = $altBin }
    }

    $essentialDlls = @(
        'Rock.dll',
        'Rock.Common.dll',
        'Rock.Enums.dll',
        'Rock.ViewModels.dll',
        'Rock.Blocks.dll',
        'Rock.Rest.dll',
        'Rock.Migrations.dll',
        'Rock.WebStartup.dll',
        'DotLiquid.dll',
        # Third-party canary for .refresh resolution: Application_Start loads it
        # via the Google/Firebase stack.
        'Google.Protobuf.dll'
    )

    foreach ($dll in $essentialDlls) {
        if (-not (Test-Path -LiteralPath (Join-Path $binDir $dll))) {
            $failures.Add("missing assembly: $dll")
        }
    }

    $blocksDir = Join-Path $RootPath (Join-Path 'Obsidian' 'Blocks')
    $obsidianBlocks = @(Get-ChildItem -Path $blocksDir -Recurse -Filter '*.obs.js' -File -ErrorAction SilentlyContinue)
    if ($obsidianBlocks.Count -eq 0) {
        $failures.Add('no compiled Obsidian blocks found under RockWeb/Obsidian/Blocks')
    }

    $obsidianCore = Join-Path $RootPath (Join-Path 'Obsidian' 'obsidian-core.js')
    if (-not (Test-Path -LiteralPath $obsidianCore)) {
        $warnings.Add('RockWeb/Obsidian/obsidian-core.js not found; Obsidian framework bundle may be missing.')
    }

    # styles-v2 is committed on 18.4.1 and generated by Rock.Frontend.Styles on 19.x.
    $tablerIcons = Join-Path $RootPath (Join-Path 'Styles' (Join-Path 'styles-v2' (Join-Path 'icons' 'tabler-icon.css')))
    if (-not (Test-Path -LiteralPath $tablerIcons)) {
        $failures.Add("missing $tablerIcons -- _rock-core.less imports it, so every LESS theme will fail to compile and the site will silently serve stale CSS")
    }
    elseif ((Get-Item -LiteralPath $tablerIcons).Length -lt 50KB) {
        $failures.Add("$tablerIcons is only $((Get-Item -LiteralPath $tablerIcons).Length) bytes; it is truncated or empty (a healthy sheet is 250KB-350KB depending on the Rock line)")
    }

    $stylesV2Dir = Join-Path $RootPath (Join-Path 'Styles' 'styles-v2')
    $stylesV2 = @(Get-ChildItem -Path $stylesV2Dir -Recurse -File -ErrorAction SilentlyContinue)
    $coreCss = Join-Path $stylesV2Dir 'core.css'
    if (-not (Test-Path -LiteralPath $coreCss)) {
        $failures.Add("missing $coreCss -- the styles-v2 build emitted no core stylesheet, so every page renders unstyled")
    }
    else {
        $coreBytes = (Get-Item -LiteralPath $coreCss).Length
        if ($coreBytes -lt 100KB) {
            $failures.Add("$coreCss is only $coreBytes bytes; the SCSS compile emitted a stub rather than the core stylesheet")
        }
    }

    $dllCount = @(Get-ChildItem -LiteralPath $binDir -File -Filter '*.dll' -ErrorAction SilentlyContinue).Count
    $totalFiles = @(Get-ChildItem -LiteralPath $RootPath -Recurse -File -ErrorAction SilentlyContinue).Count

    return [pscustomobject]@{
        Success = ($failures.Count -eq 0)
        Failures = $failures.ToArray()
        Warnings = $warnings.ToArray()
        EssentialCount = $essentialDlls.Count
        ObsidianBlockCount = $obsidianBlocks.Count
        StylesV2Count = $stylesV2.Count
        DllCount = $dllCount
        TotalFiles = $totalFiles
    }
}

if ($MyInvocation.InvocationName -ne '.') {
    $result = Test-RockWebBuild -RootPath $RockWebPath
    foreach ($warning in $result.Warnings) {
        Write-Host "::warning::$warning"
    }
    if (-not $result.Success) {
        foreach ($failure in $result.Failures) {
            Write-Host "::error::$failure"
        }
        Write-Host '::error::Artifact is incomplete and will not be packaged.'
        exit 1
    }

    $resolved = if ($ResolvedRefreshCount) { $ResolvedRefreshCount } elseif ($env:RESOLVED_REFRESH_COUNT) { $env:RESOLVED_REFRESH_COUNT } else { 'n/a' }
    $unresolved = if ($UnresolvedRefreshCount) { $UnresolvedRefreshCount } elseif ($env:UNRESOLVED_REFRESH_COUNT) { $env:UNRESOLVED_REFRESH_COUNT } else { 'n/a' }

    Write-Host 'All essential assemblies present'
    Write-Host "Obsidian blocks compiled: $($result.ObsidianBlockCount)"
    Write-Host "styles-v2 files: $($result.StylesV2Count)"
    Write-Host "Total files in RockWeb: $($result.TotalFiles)"
    Write-Host "DLLs in Bin folder: $($result.DllCount)"

    if ($env:GITHUB_STEP_SUMMARY) {
        @(
            '### Artifact verification',
            '',
            '| Check | Result |',
            '| --- | --- |',
            "| Essential assemblies | $($result.EssentialCount)/$($result.EssentialCount) present |",
            "| Compiled Obsidian blocks | $($result.ObsidianBlockCount) |",
            "| DLLs in ``RockWeb/Bin`` | $($result.DllCount) |",
            "| Assemblies resolved from ``.refresh`` | $resolved |",
            "| Unresolved ``.refresh`` pointers | $unresolved |"
        ) -join "`n" | Out-File -FilePath $env:GITHUB_STEP_SUMMARY -Append
    }
}
